/* Normaliseer één bericht uit de Gmail-node tot één vorm.
 *
 * DIT BESTAND DRAAIT OP TWEE PLEKKEN. Het is de bron van de Code-node
 * "Normaliseer bericht" in docs/n8n/lavega-invoices.json: `pnpm run sync:n8n`
 * kopieert de tekst hieronder letterlijk die node in. Daarom staat er geen
 * TypeScript-syntax in — types staan in JSDoc, en die overleeft de kopie.
 *
 * Wat hier misging (16 aug 2026): het model kreeg 768 invoer-tokens. Geen PDF,
 * en van sommige mails geen tekst. Twee oorzaken:
 *   1. Download Attachments stond in de Gmail-node náást Simplify in plaats van
 *      IN Options. n8n leest alleen `options.downloadAttachments`, dus er kwam
 *      nooit een bijlage mee. Dat is in de node zelf rechtgezet.
 *   2. Deze normalisatie las alleen `j.text` en `j.snippet`. Onder Simplify OFF
 *      bestaat `snippet` niet (n8n bouwt het item opnieuw op uit id, threadId,
 *      labelIds en sizeEstimate) en zet mailparser `text` NIET als de mail
 *      alleen een text/html-deel heeft — de gewoonste vorm van een
 *      factuurmail. Zulke mails leverden een lege tekst en vielen stil weg.
 *
 * Daarom leest dit blok nu `text`, `textAsHtml` én `html`, kiest de langste, en
 * zegt in `textSource` welke het geworden is. Wat niet gelezen kon worden, wordt
 * gemeld (`reason`, `skipped`) en nooit als "geen factuur" weggeslikt.
 */

/**
 * Eén bijlage zoals de adapter hem uit `item.binary` haalt.
 * @typedef {{ key: string, fileName: string, mimeType: string, data: string }} MailAttachment
 */

/**
 * Een PDF die aan het model meegaat. `bytes` is de echte grootte, niet de
 * base64-lengte.
 * @typedef {{ name: string, data: string, bytes: number }} InvoicePdf
 */

/**
 * De vorm waar alles ná dit punt op werkt. `source` staat er als unie in en niet
 * als 'gmail': dit is de GEDEELDE vorm, en normalizeInboundMail.js levert hem
 * ook. Zou hier 'gmail' staan, dan zou de tweede envelop een eigen type nodig
 * hebben, en een eigen type is het begin van een tweede pijplijn.
 *
 * @typedef {Object} NormalizedMessage
 * @property {'gmail'|'inbound-mail'} source
 * @property {string} messageId
 * @property {string} subject
 * @property {string} from
 * @property {string} date
 * @property {string} text            de leesbare hoofdtekst, afgekapt
 * @property {'text'|'textAsHtml'|'html'|'snippet'|'none'} textSource  waar die tekst vandaan komt
 * @property {number} textChars       lengte VÓÓR het afkappen
 * @property {boolean} truncated
 * @property {InvoicePdf[]} pdfs
 * @property {string[]} skipped       bijlagen die we bewust niet meesturen, met reden
 * @property {boolean} ok             valt er iets te lezen voor het model?
 * @property {string} reason          waarom niet, als ok false is ('' als ok true is)
 */

/** Meer dan drie PDF's per mail is bijna altijd een nieuwsbrief, geen factuur. */
const MAX_PDFS = 3;
/** Claude weigert documenten boven ongeveer deze grootte. */
const MAX_PDF_BYTES = 4 * 1024 * 1024;
/** Genoeg voor een factuurmail; daarboven betaal je voor voetteksten. */
const MAX_TEXT_CHARS = 6000;
/** Korter dan dit is een onderwerpregel, geen tekst om een factuur uit te lezen. */
const MIN_TEXT_CHARS = 40;

/**
 * @param {unknown} v
 * @returns {string}
 */
function asString(v) {
  return typeof v === 'string' ? v : '';
}

/**
 * Lees een header uit wat mailparser levert: een adresobject met `.text`, of
 * een hele headerregel ("From: Naam <naam@voorbeeld.nl>" — mailparser zet in
 * `headers` de HELE regel, niet alleen de waarde), of gewoon een string.
 * @param {unknown} v
 * @returns {string}
 */
function readHeader(v) {
  if (typeof v === 'string') return v.replace(/^[A-Za-z-]+:\s*/, '').trim();
  if (v && typeof v === 'object') {
    const o = /** @type {Record<string, unknown>} */ (v);
    if (typeof o.text === 'string') return o.text.trim();
    if (Array.isArray(o.value) && o.value.length > 0) {
      const first = /** @type {Record<string, unknown>} */ (o.value[0]);
      const name = asString(first.name);
      const address = asString(first.address);
      return (name ? name + ' <' + address + '>' : address).trim();
    }
  }
  return '';
}

/**
 * HTML naar leesbare tekst. Geen echte parser: blokelementen worden
 * regelovergangen, de rest verdwijnt. Voor een factuurtabel is dat genoeg —
 * bedragen en labels blijven op eigen regels staan.
 * @param {string} html
 * @returns {string}
 */
function stripHtml(html) {
  return html
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6]|table|thead|tbody|section|article)>/gi, '\n')
    .replace(/<\/t[dh]>/gi, ' │ ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&euro;/gi, '€')
    .replace(/[ \t ]+/g, ' ')
    .split('\n')
    .map(function (line) {
      return line.replace(/\s*│\s*$/, '').trim();
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Platte tekst opschonen zonder tags te strippen: in text/plain is "10 < 12"
 * gewoon tekst, en een tagfilter zou daar een gat in maken.
 * @param {string} text
 * @returns {string}
 */
function tidyText(text) {
  return text
    .replace(/\r\n/g, '\n')
    .replace(/[ \t ]+/g, ' ')
    .split('\n')
    .map(function (line) {
      return line.trim();
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Kies de hoofdtekst. mailparser vult `text` alleen bij een text/plain-deel;
 * een mail met uitsluitend HTML levert `html` en verder niets. Veel
 * leveranciers sturen daarnáást een text/plain van twee regels ("Bekijk uw
 * factuur online") met de hele factuur in de HTML — vandaar: pak de LANGSTE,
 * niet de eerste.
 * @param {Record<string, unknown>} j
 * @returns {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }}
 */
function pickBody(j) {
  /** @type {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }[]} */
  const candidates = [
    { text: tidyText(asString(j.text)), textSource: 'text' },
    { text: stripHtml(asString(j.textAsHtml)), textSource: 'textAsHtml' },
    { text: stripHtml(asString(j.html)), textSource: 'html' },
    // `snippet` bestaat niet onder Simplify OFF, maar kost niets als laatste
    // redmiddel — en als iemand de node ooit anders zet, is het er wél.
    { text: tidyText(asString(j.snippet)), textSource: 'snippet' },
  ];
  /** @type {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }} */
  let best = { text: '', textSource: 'none' };
  for (const candidate of candidates) {
    if (candidate.text.length > best.text.length) best = candidate;
  }
  return best;
}

/**
 * Alleen tekens die in base64 voorkomen, en een lengte die een veelvoud van vier
 * is. Een opslagverwijzing bevat een dubbele punt en streepjes en valt hier dus
 * meteen af — precies het onderscheid dat we nodig hebben.
 *
 * @param {string} value
 * @returns {boolean}
 */
function isBase64(value) {
  const clean = String(value).replace(/\s+/g, '');
  if (clean.length === 0 || clean.length % 4 !== 0) return false;
  return /^[A-Za-z0-9+/]+={0,2}$/.test(clean);
}

/**
 * Uit alle bijlagen alleen de PDF's, met een reden voor elke die afvalt.
 *
 * `source` bepaalt alleen de TEKST van die redenen, niet de regels. Dat moet
 * wel: "controleer N8N_DEFAULT_BINARY_DATA_MODE" is voor een mail die via het
 * doorstuuradres binnenkwam een instelling die er niets mee te maken heeft, en
 * een melding die naar de verkeerde knop wijst is erger dan geen melding.
 *
 * @param {MailAttachment[]} attachments
 * @param {'gmail'|'inbound-mail'} source
 * @returns {{ pdfs: InvoicePdf[], skipped: string[] }}
 */
function pickPdfs(attachments, source) {
  /** @type {InvoicePdf[]} */
  const pdfs = [];
  /** @type {string[]} */
  const skipped = [];
  for (const attachment of attachments) {
    const name = attachment.fileName || attachment.key;
    const type = attachment.mimeType.toLowerCase();
    const looksPdf = type === 'application/pdf' || /\.pdf$/i.test(name);
    // Een logo van 4 kB uit een handtekening is geen factuur en kost wel tokens.
    if (!looksPdf) continue;
    if (!attachment.data) {
      // n8n bewaart binaire data soms buiten het item (N8N_DEFAULT_BINARY_DATA_MODE
      // op filesystem/s3/database). Dan staat hier geen base64 en mag dit NIET
      // als "geen bijlage" doorgaan.
      skipped.push(
        source === 'inbound-mail'
          ? name + ': de Worker stuurde geen inhoud mee voor deze bijlage'
          : name + ': n8n leverde geen inhoud (binaire opslag staat niet op default)',
      );
      continue;
    }
    // base64 is ~4/3 van de bytes; zo weten we de grootte zonder te decoderen.
    const bytes = Math.floor((attachment.data.length * 3) / 4);
    if (bytes > MAX_PDF_BYTES) {
      skipped.push(name + ': ' + Math.round(bytes / 1024 / 1024) + ' MB, groter dan de limiet van 4 MB');
      continue;
    }
    // Is dit ECHT base64? Toen n8n zijn binaire opslag buiten het item had staan,
    // bevatte `data` een verwijzing ("filesystem-v2:workflows/...") in plaats van
    // de bytes. Die ging ongecontroleerd mee en Claude antwoordde met "Invalid
    // base64 data" — een fout die pas bij de aanbieder aan het licht kwam. Liever
    // hier weigeren en het MELDEN dan iets versturen dat we niet gelezen hebben.
    if (!isBase64(attachment.data)) {
      skipped.push(
        source === 'inbound-mail'
          ? name +
              ': de inhoud is geen base64 maar een verwijzing — de Worker stuurde een opslagverwijzing in plaats van de bytes'
          : name + ': de inhoud is geen base64 maar een verwijzing — controleer N8N_DEFAULT_BINARY_DATA_MODE',
      );
      continue;
    }
    if (pdfs.length >= MAX_PDFS) {
      skipped.push(name + ': meer dan ' + MAX_PDFS + ' PDF-bijlagen in één mail');
      continue;
    }
    pdfs.push({ name: name, data: attachment.data, bytes: bytes });
  }
  return { pdfs: pdfs, skipped: skipped };
}

/**
 * @param {Record<string, unknown>} json      item.json uit de Gmail-node
 * @param {MailAttachment[]} attachments      item.binary, al opgelost door de adapter
 * @returns {NormalizedMessage}
 */
function normalizeGmailMessage(json, attachments) {
  const j = json || {};
  const headers = /** @type {Record<string, unknown>} */ (
    j.headers && typeof j.headers === 'object' ? j.headers : {}
  );

  const subject = asString(j.subject) || readHeader(headers.subject);
  const from = readHeader(j.from) || readHeader(headers.from) || asString(j.From);
  const date = asString(j.date) || readHeader(headers.date) || asString(j.internalDate);

  const body = pickBody(j);
  const textChars = body.text.length;
  const text = body.text.slice(0, MAX_TEXT_CHARS);
  const picked = pickPdfs(Array.isArray(attachments) ? attachments : [], 'gmail');

  const ok = picked.pdfs.length > 0 || text.length >= MIN_TEXT_CHARS;
  let reason = '';
  if (!ok) {
    if (j.payload) {
      reason =
        'De Gmail-node leverde een onbewerkte payload in plaats van gelezen tekst. ' +
        'Zet Simplify uit in de node "Gmail: recente mail".';
    } else if (textChars > 0) {
      reason = 'Maar ' + textChars + ' tekens tekst en geen PDF-bijlage.';
    } else {
      reason = 'Geen leesbare tekst en geen PDF-bijlage in dit bericht.';
    }
  }

  return {
    source: 'gmail',
    messageId: asString(j.id) || asString(j.messageId),
    subject: subject,
    from: from,
    date: date,
    text: text,
    textSource: textChars === 0 ? 'none' : body.textSource,
    textChars: textChars,
    truncated: textChars > text.length,
    pdfs: picked.pdfs,
    skipped: picked.skipped,
    ok: ok,
    reason: reason,
  };
}

/* Normaliseer één bericht dat via het DOORSTUURADRES binnenkwam.
 *
 * DIT BESTAND DRAAIT OP TWEE PLEKKEN. Het is, samen met
 * normalizeGmailMessage.js, de bron van de Code-node "Normaliseer binnengekomen
 * mail" in docs/n8n/lavega-invoices.json: `pnpm run sync:n8n` plakt beide
 * bestanden achter elkaar in die node. Daarom staat er geen TypeScript-syntax
 * in — types staan in JSDoc — en daarom worden de `import`-regels hieronder bij
 * het genereren wéggehaald: in n8n staat de inhoud van
 * normalizeGmailMessage.js er letterlijk bóven, dus die functies bestaan daar
 * gewoon in dezelfde scope.
 *
 * WAAROM DIT GEEN TWEEDE NORMALISATIE IS. Alles wat betekenis heeft — welke
 * tekst de hoofdtekst is, welke bijlage een factuur kan zijn, wanneer er niets
 * te lezen valt — komt uit `pickBody` en `pickPdfs` hiernaast, precies dezelfde
 * functies die de Gmail-tak gebruikt en die daar getest zijn. Wat hier staat is
 * alleen de ENVELOP: welk veld van de Cloudflare Email Worker welk veld van een
 * bericht is. Twee normalisaties naast elkaar zouden binnen een maand uit elkaar
 * lopen, en de eerste die dat merkt is een gemiste factuur.
 *
 * WAT HIER ANDERS IS DAN BIJ GMAIL, en waarom dat er in de rij bij moet staan:
 *
 *   1. HERKOMST. Een mail uit Gmail is per definitie zijn eigen mail. Een mail
 *      op het doorstuuradres kan van iedereen komen die het adres kent. Daarom
 *      dragen deze regels `deliveredTo` (op welk adres hij binnenkwam) en
 *      `from` (wie hem stuurde) mee tot in de wachtrij: hij moet een regel die
 *      hij niet verwachtte kunnen beoordelen.
 *
 *   2. DE AFZENDER IS NIET GECONTROLEERD. `senderChecks` is wat Cloudflare in
 *      de header `Authentication-Results` zette, letterlijk doorgegeven.
 *      `senderCheck` vat dat samen in drie standen — 'passed', 'failed',
 *      'unknown' — en 'passed' betekent uitsluitend dat het DOMEIN de controle
 *      doorstond, niet dat de factuur echt is. Een mail die zakt wordt GEMARKEERD,
 *      niet weggegooid: wegggooien is het enige wat erger is dan een nepfactuur
 *      tonen, want dan mist hij een echte zonder het te weten.
 *
 *   3. GEEN GMAIL-LINK. `toQueueEntry` zet `mailUrl` alleen voor bron 'gmail'.
 *      Een mail-id uit een doorgestuurd bericht in een Gmail-URL plakken levert
 *      een link op die naar niets wijst; dat is een advies dat niet kan werken.
 */



/** @typedef {import('./normalizeGmailMessage.js').InvoicePdf} InvoicePdf */

/**
 * Eén bijlage zoals de Worker hem in de JSON zet: de bytes als base64, niets
 * meer. Er is geen n8n-binaire opslag in dit pad.
 * @typedef {{ fileName: string, mimeType: string, data: string }} InboundAttachment
 */

/**
 * De uitslag van SPF/DKIM/DMARC zoals Cloudflare hem in `Authentication-Results`
 * zet. Een waarde die we niet kennen — of een ontbrekende header — wordt
 * 'unknown'. NOOIT 'pass': onbekend is geen goedkeuring.
 * @typedef {'pass'|'fail'|'softfail'|'neutral'|'none'|'temperror'|'permerror'|'unknown'} AuthResult
 */

/**
 * @typedef {{ spf: AuthResult, dkim: AuthResult, dmarc: AuthResult }} SenderChecks
 */

/**
 * Wat de Cloudflare Email Worker POST naar de webhook "E-mail binnen".
 * @typedef {Object} InboundMailPayload
 * @property {string} to          het volledige adres waarop de mail binnenkwam
 * @property {string} queueKey    het lokale deel daarvan; identificeert de rij
 * @property {string} from        de afzender, ONGECONTROLEERD
 * @property {string} subject
 * @property {string} date
 * @property {string} messageId
 * @property {string} text        het text/plain-deel, leeg als het er niet was
 * @property {string} html        het text/html-deel, leeg als het er niet was
 * @property {SenderChecks} [auth]
 * @property {InboundAttachment[]} attachments
 */

/**
 * Precies de gedeelde vorm uit normalizeGmailMessage.js, plus de herkomst. Dit
 * is met opzet een UITBREIDING en geen eigen typedef: zodra de twee vormen los
 * van elkaar opgeschreven staan, kunnen ze los van elkaar veranderen.
 *
 * @typedef {import('./normalizeGmailMessage.js').NormalizedMessage & {
 *   deliveredTo: string,
 *   queueKey: string,
 *   senderChecks: SenderChecks,
 *   senderCheck: 'passed'|'failed'|'unknown'
 * }} NormalizedInboundMessage
 */

/** De uitslagen die SPF/DKIM/DMARC volgens RFC 7601 kunnen geven. */
const AUTH_RESULTS = ['pass', 'fail', 'softfail', 'neutral', 'none', 'temperror', 'permerror'];

/**
 * Alles wat we niet als geldige uitslag herkennen wordt 'unknown'. Dit is de
 * plek waar de regel "onbekend is nooit stilzwijgend een waarde" wordt
 * afgedwongen: een ontbrekende of rare `auth` levert drie keer 'unknown' op, en
 * dat is zichtbaar iets anders dan drie keer 'pass'.
 * @param {unknown} v
 * @returns {AuthResult}
 */
function readAuthResult(v) {
  const value = asString(v).toLowerCase().trim();
  return AUTH_RESULTS.indexOf(value) >= 0 ? /** @type {AuthResult} */ (value) : 'unknown';
}

/**
 * @param {unknown} v
 * @returns {SenderChecks}
 */
function readSenderChecks(v) {
  const o = /** @type {Record<string, unknown>} */ (v && typeof v === 'object' ? v : {});
  return { spf: readAuthResult(o.spf), dkim: readAuthResult(o.dkim), dmarc: readAuthResult(o.dmarc) };
}

/**
 * Drie standen, en de derde is het punt. Een mail waarvan we NIETS weten mag
 * niet dezelfde kleur krijgen als een mail die de controle doorstond.
 *
 * 'failed'  — minstens één controle zakte (fail, softfail of permerror).
 * 'passed'  — niets zakte én SPF of DKIM stond echt op 'pass'.
 * 'unknown' — al het andere: geen header, tijdelijke fout, alleen 'none'.
 *
 * 'passed' zegt: deze mail kwam echt van dat domein. Het zegt NIETS over de
 * vraag of de factuur klopt.
 * @param {SenderChecks} checks
 * @returns {'passed'|'failed'|'unknown'}
 */
function senderCheckOf(checks) {
  const bad = ['fail', 'softfail', 'permerror'];
  if (bad.indexOf(checks.spf) >= 0 || bad.indexOf(checks.dkim) >= 0 || bad.indexOf(checks.dmarc) >= 0) {
    return 'failed';
  }
  if (checks.spf === 'pass' || checks.dkim === 'pass') return 'passed';
  return 'unknown';
}

/**
 * Waarom viel er niets te lezen? De vraag is niet retorisch: elk van deze
 * antwoorden wijst een andere knop aan, en een melding die de verkeerde
 * aanwijst kost hem een middag.
 * @param {number} textChars
 * @param {string[]} skipped
 * @param {number} attachmentCount
 * @returns {string}
 */
function reasonForUnreadable(textChars, skipped, attachmentCount) {
  if (skipped.length > 0) {
    return 'Geen leesbare tekst, en de bijlage ging niet mee — ' + skipped.join('; ') + '.';
  }
  if (textChars > 0) {
    return 'Maar ' + textChars + ' tekens tekst en geen PDF-bijlage in de doorgestuurde mail.';
  }
  if (attachmentCount > 0) {
    return (
      'Geen leesbare tekst, en van de ' +
      attachmentCount +
      ' bijlage(n) was er geen enkele een PDF. Een gescande bon als afbeelding wordt niet gelezen; stuur de PDF door.'
    );
  }
  return 'Geen leesbare tekst en geen bijlage in de doorgestuurde mail.';
}

/**
 * @param {InboundMailPayload|Record<string, unknown>} payload
 * @returns {NormalizedInboundMessage}
 */
function normalizeInboundMail(payload) {
  const p = /** @type {Record<string, unknown>} */ (payload && typeof payload === 'object' ? payload : {});

  // pickBody kijkt naar text / textAsHtml / html en pakt de LANGSTE. Bij gelijke
  // lengte wint text/plain, want die staat vooraan in zijn kandidatenlijst — en
  // dat is precies de voorkeur die hier hoort. Alleen text/plain nemen zou de
  // fout van 16 augustus herhalen: de leverancier stuurt twee regels platte
  // tekst ("Bekijk uw factuur online") náást de hele factuur in HTML.
  const body = pickBody({ text: asString(p.text), html: asString(p.html) });
  const textChars = body.text.length;
  const text = body.text.slice(0, MAX_TEXT_CHARS);

  const rawAttachments = Array.isArray(p.attachments) ? p.attachments : [];
  const attachments = rawAttachments.map(function (a, index) {
    const o = /** @type {Record<string, unknown>} */ (a && typeof a === 'object' ? a : {});
    return {
      key: 'attachment_' + index,
      fileName: asString(o.fileName),
      mimeType: asString(o.mimeType),
      data: asString(o.data),
    };
  });
  const picked = pickPdfs(attachments, 'inbound-mail');

  const ok = picked.pdfs.length > 0 || text.length >= MIN_TEXT_CHARS;
  const senderChecks = readSenderChecks(p.auth);

  return {
    source: 'inbound-mail',
    messageId: asString(p.messageId),
    subject: asString(p.subject),
    from: asString(p.from),
    date: asString(p.date),
    text: text,
    textSource: textChars === 0 ? 'none' : body.textSource,
    textChars: textChars,
    truncated: textChars > text.length,
    pdfs: picked.pdfs,
    skipped: picked.skipped,
    ok: ok,
    reason: ok ? '' : reasonForUnreadable(textChars, picked.skipped, attachments.length),
    deliveredTo: asString(p.to),
    queueKey: asString(p.queueKey),
    senderChecks: senderChecks,
    senderCheck: senderCheckOf(senderChecks),
  };
}

// ── n8n-adapter ─────────────────────────────────────────────────────────
// Alles hierboven is LETTERLIJK gekopieerd uit packages/core/src/n8n/ en
// wordt daar getest. Wijzig het daar en draai `pnpm run sync:n8n`; wijzig je
// het hier of in de n8n-UI, dan valt `codeNodes.test.ts` om.

// Eén POST van de Cloudflare Email Worker = één doorgestuurde mail. De
// webhook-node zet de JSON-body op item.json.body; staat daar niets, dan is
// dat GEEN lege mail maar een verkeerd afgeleverd verzoek, en dan moet deze
// node omvallen zodat de Worker een niet-2xx ziet en de afzender een bounce
// krijgt. Stil doorgaan zou de mail laten verdwijnen — het enige wat we hier
// echt niet mogen.
const items = $input.all();
const out = [];
for (const item of items) {
  const body = (item.json && item.json.body) || null;
  if (!body || typeof body !== 'object') {
    throw new Error('De webhook kreeg geen JSON-body. Controleer of de Worker Content-Type: application/json stuurt en of de node op POST staat.');
  }
  out.push({ json: normalizeInboundMail(body) });
}
// GEEN filter op seenIds hier, anders dan bij Gmail. De Gmail-tak loopt elk
// uur over dezelfde zeven dagen en moet zichzelf remmen; een doorgestuurde
// mail is een handeling van de eigenaar. Stuurt hij er één opnieuw door omdat
// de eerste niet aankwam, dan hoort die opnieuw verwerkt te worden — en niet
// stil te verdwijnen omdat hij ooit al eens langskwam.
return out;

/* Normaliseer één bericht uit de Gmail-node tot één vorm.
 *
 * DIT BESTAND DRAAIT OP TWEE PLEKKEN. Het is de bron van de Code-node
 * "Normaliseer bericht" in docs/n8n/lavega-invoices.json: `pnpm run sync:n8n`
 * kopieert de tekst hieronder letterlijk die node in. Daarom staat er geen
 * TypeScript-syntax in — types staan in JSDoc, en die overleeft de kopie.
 *
 * Wat hier misging (16 aug 2026): het model kreeg 768 invoer-tokens. Geen PDF,
 * en van sommige mails geen tekst. Twee oorzaken:
 *   1. Download Attachments stond in de Gmail-node náást Simplify in plaats van
 *      IN Options. n8n leest alleen `options.downloadAttachments`, dus er kwam
 *      nooit een bijlage mee. Dat is in de node zelf rechtgezet.
 *   2. Deze normalisatie las alleen `j.text` en `j.snippet`. Onder Simplify OFF
 *      bestaat `snippet` niet (n8n bouwt het item opnieuw op uit id, threadId,
 *      labelIds en sizeEstimate) en zet mailparser `text` NIET als de mail
 *      alleen een text/html-deel heeft — de gewoonste vorm van een
 *      factuurmail. Zulke mails leverden een lege tekst en vielen stil weg.
 *
 * Daarom leest dit blok nu `text`, `textAsHtml` én `html`, kiest de langste, en
 * zegt in `textSource` welke het geworden is. Wat niet gelezen kon worden, wordt
 * gemeld (`reason`, `skipped`) en nooit als "geen factuur" weggeslikt.
 */

/**
 * Eén bijlage zoals de adapter hem uit `item.binary` haalt.
 * @typedef {{ key: string, fileName: string, mimeType: string, data: string }} MailAttachment
 */

/**
 * Een PDF die aan het model meegaat. `bytes` is de echte grootte, niet de
 * base64-lengte.
 * @typedef {{ name: string, data: string, bytes: number }} InvoicePdf
 */

/**
 * De vorm waar alles ná dit punt op werkt. `source` staat er als unie in en niet
 * als 'gmail': dit is de GEDEELDE vorm, en normalizeInboundMail.js levert hem
 * ook. Zou hier 'gmail' staan, dan zou de tweede envelop een eigen type nodig
 * hebben, en een eigen type is het begin van een tweede pijplijn.
 *
 * @typedef {Object} NormalizedMessage
 * @property {'gmail'|'inbound-mail'} source
 * @property {string} messageId
 * @property {string} subject
 * @property {string} from
 * @property {string} date
 * @property {string} text            de leesbare hoofdtekst, afgekapt
 * @property {'text'|'textAsHtml'|'html'|'snippet'|'none'} textSource  waar die tekst vandaan komt
 * @property {number} textChars       lengte VÓÓR het afkappen
 * @property {boolean} truncated
 * @property {InvoicePdf[]} pdfs
 * @property {string[]} skipped       bijlagen die we bewust niet meesturen, met reden
 * @property {boolean} ok             valt er iets te lezen voor het model?
 * @property {string} reason          waarom niet, als ok false is ('' als ok true is)
 */

/** Meer dan drie PDF's per mail is bijna altijd een nieuwsbrief, geen factuur. */
const MAX_PDFS = 3;
/** Claude weigert documenten boven ongeveer deze grootte. */
const MAX_PDF_BYTES = 4 * 1024 * 1024;
/** Genoeg voor een factuurmail; daarboven betaal je voor voetteksten. */
const MAX_TEXT_CHARS = 6000;
/** Korter dan dit is een onderwerpregel, geen tekst om een factuur uit te lezen. */
const MIN_TEXT_CHARS = 40;

/**
 * @param {unknown} v
 * @returns {string}
 */
function asString(v) {
  return typeof v === 'string' ? v : '';
}

/**
 * Lees een header uit wat mailparser levert: een adresobject met `.text`, of
 * een hele headerregel ("From: Naam <naam@voorbeeld.nl>" — mailparser zet in
 * `headers` de HELE regel, niet alleen de waarde), of gewoon een string.
 * @param {unknown} v
 * @returns {string}
 */
function readHeader(v) {
  if (typeof v === 'string') return v.replace(/^[A-Za-z-]+:\s*/, '').trim();
  if (v && typeof v === 'object') {
    const o = /** @type {Record<string, unknown>} */ (v);
    if (typeof o.text === 'string') return o.text.trim();
    if (Array.isArray(o.value) && o.value.length > 0) {
      const first = /** @type {Record<string, unknown>} */ (o.value[0]);
      const name = asString(first.name);
      const address = asString(first.address);
      return (name ? name + ' <' + address + '>' : address).trim();
    }
  }
  return '';
}

/**
 * HTML naar leesbare tekst. Geen echte parser: blokelementen worden
 * regelovergangen, de rest verdwijnt. Voor een factuurtabel is dat genoeg —
 * bedragen en labels blijven op eigen regels staan.
 * @param {string} html
 * @returns {string}
 */
function stripHtml(html) {
  return html
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6]|table|thead|tbody|section|article)>/gi, '\n')
    .replace(/<\/t[dh]>/gi, ' │ ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&euro;/gi, '€')
    .replace(/[ \t ]+/g, ' ')
    .split('\n')
    .map(function (line) {
      return line.replace(/\s*│\s*$/, '').trim();
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Platte tekst opschonen zonder tags te strippen: in text/plain is "10 < 12"
 * gewoon tekst, en een tagfilter zou daar een gat in maken.
 * @param {string} text
 * @returns {string}
 */
function tidyText(text) {
  return text
    .replace(/\r\n/g, '\n')
    .replace(/[ \t ]+/g, ' ')
    .split('\n')
    .map(function (line) {
      return line.trim();
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/**
 * Kies de hoofdtekst. mailparser vult `text` alleen bij een text/plain-deel;
 * een mail met uitsluitend HTML levert `html` en verder niets. Veel
 * leveranciers sturen daarnáást een text/plain van twee regels ("Bekijk uw
 * factuur online") met de hele factuur in de HTML — vandaar: pak de LANGSTE,
 * niet de eerste.
 * @param {Record<string, unknown>} j
 * @returns {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }}
 */
function pickBody(j) {
  /** @type {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }[]} */
  const candidates = [
    { text: tidyText(asString(j.text)), textSource: 'text' },
    { text: stripHtml(asString(j.textAsHtml)), textSource: 'textAsHtml' },
    { text: stripHtml(asString(j.html)), textSource: 'html' },
    // `snippet` bestaat niet onder Simplify OFF, maar kost niets als laatste
    // redmiddel — en als iemand de node ooit anders zet, is het er wél.
    { text: tidyText(asString(j.snippet)), textSource: 'snippet' },
  ];
  /** @type {{ text: string, textSource: 'text'|'textAsHtml'|'html'|'snippet'|'none' }} */
  let best = { text: '', textSource: 'none' };
  for (const candidate of candidates) {
    if (candidate.text.length > best.text.length) best = candidate;
  }
  return best;
}

/**
 * Alleen tekens die in base64 voorkomen, en een lengte die een veelvoud van vier
 * is. Een opslagverwijzing bevat een dubbele punt en streepjes en valt hier dus
 * meteen af — precies het onderscheid dat we nodig hebben.
 *
 * @param {string} value
 * @returns {boolean}
 */
function isBase64(value) {
  const clean = String(value).replace(/\s+/g, '');
  if (clean.length === 0 || clean.length % 4 !== 0) return false;
  return /^[A-Za-z0-9+/]+={0,2}$/.test(clean);
}

/**
 * Uit alle bijlagen alleen de PDF's, met een reden voor elke die afvalt.
 *
 * `source` bepaalt alleen de TEKST van die redenen, niet de regels. Dat moet
 * wel: "controleer N8N_DEFAULT_BINARY_DATA_MODE" is voor een mail die via het
 * doorstuuradres binnenkwam een instelling die er niets mee te maken heeft, en
 * een melding die naar de verkeerde knop wijst is erger dan geen melding.
 *
 * @param {MailAttachment[]} attachments
 * @param {'gmail'|'inbound-mail'} source
 * @returns {{ pdfs: InvoicePdf[], skipped: string[] }}
 */
function pickPdfs(attachments, source) {
  /** @type {InvoicePdf[]} */
  const pdfs = [];
  /** @type {string[]} */
  const skipped = [];
  for (const attachment of attachments) {
    const name = attachment.fileName || attachment.key;
    const type = attachment.mimeType.toLowerCase();
    const looksPdf = type === 'application/pdf' || /\.pdf$/i.test(name);
    // Een logo van 4 kB uit een handtekening is geen factuur en kost wel tokens.
    if (!looksPdf) continue;
    if (!attachment.data) {
      // n8n bewaart binaire data soms buiten het item (N8N_DEFAULT_BINARY_DATA_MODE
      // op filesystem/s3/database). Dan staat hier geen base64 en mag dit NIET
      // als "geen bijlage" doorgaan.
      skipped.push(
        source === 'inbound-mail'
          ? name + ': de Worker stuurde geen inhoud mee voor deze bijlage'
          : name + ': n8n leverde geen inhoud (binaire opslag staat niet op default)',
      );
      continue;
    }
    // base64 is ~4/3 van de bytes; zo weten we de grootte zonder te decoderen.
    const bytes = Math.floor((attachment.data.length * 3) / 4);
    if (bytes > MAX_PDF_BYTES) {
      skipped.push(name + ': ' + Math.round(bytes / 1024 / 1024) + ' MB, groter dan de limiet van 4 MB');
      continue;
    }
    // Is dit ECHT base64? Toen n8n zijn binaire opslag buiten het item had staan,
    // bevatte `data` een verwijzing ("filesystem-v2:workflows/...") in plaats van
    // de bytes. Die ging ongecontroleerd mee en Claude antwoordde met "Invalid
    // base64 data" — een fout die pas bij de aanbieder aan het licht kwam. Liever
    // hier weigeren en het MELDEN dan iets versturen dat we niet gelezen hebben.
    if (!isBase64(attachment.data)) {
      skipped.push(
        source === 'inbound-mail'
          ? name +
              ': de inhoud is geen base64 maar een verwijzing — de Worker stuurde een opslagverwijzing in plaats van de bytes'
          : name + ': de inhoud is geen base64 maar een verwijzing — controleer N8N_DEFAULT_BINARY_DATA_MODE',
      );
      continue;
    }
    if (pdfs.length >= MAX_PDFS) {
      skipped.push(name + ': meer dan ' + MAX_PDFS + ' PDF-bijlagen in één mail');
      continue;
    }
    pdfs.push({ name: name, data: attachment.data, bytes: bytes });
  }
  return { pdfs: pdfs, skipped: skipped };
}

/**
 * @param {Record<string, unknown>} json      item.json uit de Gmail-node
 * @param {MailAttachment[]} attachments      item.binary, al opgelost door de adapter
 * @returns {NormalizedMessage}
 */
function normalizeGmailMessage(json, attachments) {
  const j = json || {};
  const headers = /** @type {Record<string, unknown>} */ (
    j.headers && typeof j.headers === 'object' ? j.headers : {}
  );

  const subject = asString(j.subject) || readHeader(headers.subject);
  const from = readHeader(j.from) || readHeader(headers.from) || asString(j.From);
  const date = asString(j.date) || readHeader(headers.date) || asString(j.internalDate);

  const body = pickBody(j);
  const textChars = body.text.length;
  const text = body.text.slice(0, MAX_TEXT_CHARS);
  const picked = pickPdfs(Array.isArray(attachments) ? attachments : [], 'gmail');

  const ok = picked.pdfs.length > 0 || text.length >= MIN_TEXT_CHARS;
  let reason = '';
  if (!ok) {
    if (j.payload) {
      reason =
        'De Gmail-node leverde een onbewerkte payload in plaats van gelezen tekst. ' +
        'Zet Simplify uit in de node "Gmail: recente mail".';
    } else if (textChars > 0) {
      reason = 'Maar ' + textChars + ' tekens tekst en geen PDF-bijlage.';
    } else {
      reason = 'Geen leesbare tekst en geen PDF-bijlage in dit bericht.';
    }
  }

  return {
    source: 'gmail',
    messageId: asString(j.id) || asString(j.messageId),
    subject: subject,
    from: from,
    date: date,
    text: text,
    textSource: textChars === 0 ? 'none' : body.textSource,
    textChars: textChars,
    truncated: textChars > text.length,
    pdfs: picked.pdfs,
    skipped: picked.skipped,
    ok: ok,
    reason: reason,
  };
}

// ── n8n-adapter ─────────────────────────────────────────────────────────
// Alles hierboven is LETTERLIJK gekopieerd uit packages/core/src/n8n/ en
// wordt daar getest. Wijzig het daar en draai `pnpm run sync:n8n`; wijzig je
// het hier of in de n8n-UI, dan valt `codeNodes.test.ts` om.

const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.seenIds)) store.seenIds = [];
const seen = new Set(store.seenIds);
const helpers = typeof this !== 'undefined' && this && this.helpers ? this.helpers : null;

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const bin = item.binary || {};
  const attachments = [];
  for (const key of Object.keys(bin)) {
    const b = bin[key] || {};
    let data = '';
    if (b.id && helpers && helpers.getBinaryDataBuffer) {
      // b.id AANWEZIG betekent: de bytes staan NIET in het item. Dan bevat
      // b.data een verwijzing ('filesystem-v2:...'), geen base64 — en die
      // verwijzing als base64 doorsturen geeft precies de fout die we zagen:
      // "Invalid base64 data". Dus b.id beslist, niet of b.data leeg is.
      const buffer = await helpers.getBinaryDataBuffer(i, key);
      data = buffer.toString('base64');
    } else if (typeof b.data === 'string') {
      data = b.data;
    }
    attachments.push({
      key: key,
      fileName: String(b.fileName || key),
      mimeType: String(b.mimeType || ''),
      data: data,
    });
  }
  const message = normalizeGmailMessage(item.json || {}, attachments);
  // Al door het model beoordeeld in een eerdere run? Dan niet opnieuw sturen:
  // de schedule loopt elk uur over dezelfde zeven dagen mail.
  if (message.messageId && seen.has(message.messageId)) continue;
  out.push({ json: message });
}
return out;

/* Bouw het verzoek aan Claude uit één genormaliseerd bericht.
 *
 * DIT BESTAND DRAAIT OP TWEE PLEKKEN — het is de bron van de Code-node
 * "Bouw Claude-verzoek" in docs/n8n/lavega-invoices.json. `pnpm run sync:n8n`
 * kopieert het daarin. Geen TypeScript-syntax, alleen JSDoc.
 *
 * Het verzoek wordt HIER opgebouwd en niet in een expressie op de HTTP-node:
 * met base64-PDF's erin wordt zo'n expressie onleesbaar en is een fout er niet
 * meer uit te halen.
 *
 * De PDF gaat als document-blok mee. Een factuur is een LAYOUT — bedragen staan
 * in kolommen, btw staat onderaan — en die layout overleeft het platslaan naar
 * tekst niet. Het model moet de pagina zien.
 *
 * En wat het model NIET te horen krijgt is net zo belangrijk. De oude versie
 * zette altijd een regel "Bijlagen: " in het bericht, ook als er geen bijlage
 * was. Dat leest als "er zat niets bij", terwijl wij alleen weten dat n8n ons
 * niets gaf. Op precies die regel antwoordde het model "bevat geen bijlage" —
 * het herhaalde onze eigen bewering. Een lege lijst is dus geen lijst: die
 * regel valt nu weg.
 */

/** @typedef {import('./normalizeGmailMessage.js').NormalizedMessage} NormalizedMessage */

/**
 * @typedef {Object} ClaudeRequest
 * @property {string} model
 * @property {number} max_tokens
 * @property {string} system
 * @property {{ role: 'user', content: unknown[] }[]} messages
 */

const INVOICE_MODEL = 'claude-sonnet-5';

const INVOICE_SYSTEM = [
  'Je leest e-mails en bijlagen en bepaalt of er een FACTUUR in zit.',
  'Antwoord UITSLUITEND met JSON, zonder uitleg eromheen:',
  '{"isInvoice": true|false, "kind": "invoice"|"notification"|"reminder"|"receipt"|"other",',
  ' "invoiceNumber": string|null, "issueDate": "YYYY-MM-DD"|null,',
  ' "dueDate": "YYYY-MM-DD"|null, "amount": number|null, "vatAmount": number|null,',
  ' "currency": string|null, "counterparty": string|null, "direction": "expense"|"income"|null,',
  ' "note": string}',
  'kind beschrijft wat de mail IS:',
  '"invoice" = de factuur zelf staat erin (in de tekst of als bijlage);',
  '"notification" = de mail meldt een factuur die er niet in staat ("uw factuur staat klaar",',
  'inloggen bij de leverancier, een link naar een portaal) — de eigenaar moet hem zelf ophalen;',
  '"reminder" = herinnering of aanmaning voor een factuur die hij al hoorde te hebben;',
  '"receipt" = betaalbewijs of bevestiging van een betaling die al gedaan is;',
  '"other" = geen van deze.',
  'isInvoice is alleen true bij kind "invoice". Een melding, een herinnering en een',
  'betaalbewijs zijn GEEN factuur, ook niet als er een bedrag in staat.',
  'amount is het TOTAAL inclusief btw, als getal, punt als decimaalteken, zonder valutateken.',
  'currency is de valuta die OP DE FACTUUR staat, als ISO-code (EUR, USD, GBP).',
  'Neem hem niet aan: staat er geen valuta, zet dan null. LaVega vraagt het dan zelf.',
  'Een factuur in dollars die als euro wordt geboekt is geen opmaakfoutje maar een',
  'verkeerd bedrag in een boekhouding, en niets waarschuwt de eigenaar daarvoor.',
  'vatAmount is alleen het btw-bedrag.',
  'direction: "expense" als iemand GELD VAN JOU wil, "income" als jij iemand factureert.',
  'Laat een veld null als het er niet staat. Verzin nooit een bedrag of een nummer:',
  'een verzonnen factuur in een boekhouding is erger dan een gemiste factuur.',
  'note is één zin in het Nederlands: wat je zag, en bij een melding of herinnering',
  'wat de eigenaar zelf moet doen.',
  'Staat er onder "Bijlagen" niets, ga dan niet beweren dat er geen bijlage was:',
  'je ziet alleen wat je is meegegeven.',
].join(' ');

/**
 * @param {NormalizedMessage} m
 * @returns {ClaudeRequest}
 */
function buildClaudeRequest(m) {
  const pdfs = Array.isArray(m.pdfs) ? m.pdfs : [];
  /** @type {unknown[]} */
  const content = [];
  for (const pdf of pdfs) {
    content.push({
      type: 'document',
      source: { type: 'base64', media_type: 'application/pdf', data: pdf.data },
    });
  }

  /** @type {string[]} */
  const lines = [];
  lines.push('Onderwerp: ' + m.subject);
  lines.push('Afzender: ' + m.from);
  lines.push('Datum: ' + m.date);
  // Alleen een regel als er ook echt iets bij zit — zie de kop van dit bestand.
  if (pdfs.length > 0) {
    lines.push(
      'Bijlagen: ' +
        pdfs
          .map(function (p) {
            return p.name;
          })
          .join(', '),
    );
  }
  if (m.truncated) {
    lines.push('(De tekst hieronder is afgekapt; de mail was ' + m.textChars + ' tekens lang.)');
  }
  lines.push('');
  lines.push(m.text || '(deze mail had geen leesbare tekst)');

  content.push({ type: 'text', text: lines.join('\n') });

  return {
    model: INVOICE_MODEL,
    max_tokens: 1024,
    system: INVOICE_SYSTEM,
    messages: [{ role: 'user', content: content }],
  };
}

/**
 * Hoeveel tekens gaan er echt naartoe, PDF-bytes niet meegerekend? Puur om in
 * een run te kunnen zien dat het model gevoed is, in plaats van het aan de
 * tokenteller van Anthropic te moeten afleiden.
 * @param {ClaudeRequest} request
 * @returns {{ documents: number, textChars: number, pdfBytes: number }}
 */
function requestSize(request) {
  let documents = 0;
  let textChars = 0;
  let pdfBytes = 0;
  for (const block of request.messages[0].content) {
    const b = /** @type {Record<string, unknown>} */ (block);
    if (b.type === 'document') {
      documents += 1;
      const source = /** @type {Record<string, unknown>} */ (b.source);
      const data = typeof source.data === 'string' ? source.data : '';
      pdfBytes += Math.floor((data.length * 3) / 4);
    } else if (b.type === 'text') {
      textChars += typeof b.text === 'string' ? b.text.length : 0;
    }
  }
  return { documents: documents, textChars: textChars, pdfBytes: pdfBytes };
}

// ── n8n-adapter ─────────────────────────────────────────────────────────
// Alles hierboven is LETTERLIJK gekopieerd uit packages/core/src/n8n/ en
// wordt daar getest. Wijzig het daar en draai `pnpm run sync:n8n`; wijzig je
// het hier of in de n8n-UI, dan valt `codeNodes.test.ts` om.

const out = [];
for (const item of $input.all()) {
  const message = item.json;
  const request = buildClaudeRequest(message);
  const size = requestSize(request);
  out.push({ json: {
    source: message.source,
    messageId: message.messageId,
    subject: message.subject,
    from: message.from,
    date: message.date,
    // Herkomst. Bij Gmail zijn deze drie undefined en laat provenanceOf ze
    // dan ook wég uit de regel; bij een doorgestuurde mail zijn ze het enige
    // waarmee hij een onverwachte regel kan beoordelen.
    deliveredTo: message.deliveredTo,
    queueKey: message.queueKey,
    senderCheck: message.senderCheck,
    senderChecks: message.senderChecks,
    // In de run zelf te zien wat er de deur uit ging. 768 invoer-tokens zonder
    // document was het teken dat er niets meeging; dit maakt dat zichtbaar
    // zonder de tokenteller van Anthropic te hoeven lezen.
    sent: {
      documents: size.documents,
      textChars: size.textChars,
      pdfBytes: size.pdfBytes,
      textSource: message.textSource,
    },
    body: request,
  } });
}
return out;

/* Het antwoord van Claude naar de vorm die LaVega verwacht.
 *
 * DIT BESTAND DRAAIT OP DRIE PLEKKEN — het is de bron van de Code-nodes
 * "Naar LaVega-vorm" en "Melding: zelf ophalen" in
 * docs/n8n/lavega-invoices.json. `pnpm run sync:n8n` kopieert het daarin.
 * Geen TypeScript-syntax, alleen JSDoc.
 *
 * Twee soorten uitkomst, en het verschil is de hele veiligheid van deze
 * workflow:
 *
 *   FACTUUR — heeft een bedrag, en wordt in LaVega een regel die de eigenaar
 *   bevestigt. Zonder bedrag komt hij er niet in. Nooit.
 *
 *   MELDING — heeft GEEN bedragveld, ook geen leeg veld. Een melding kan dus
 *   structureel geen boeking worden; daar is geen validatie voor nodig. Het is
 *   een briefje: "hier wacht iets op je, haal het zelf op."
 *
