  };

  if (kind === 'notification') {
    return { invoice: null, notice: notice('notification', note || 'Deze mail meldt een factuur die er niet in staat; haal hem zelf op.'), dropped: null };
  }
  if (kind === 'reminder') {
    // Een aanmaning NOEMT vaak het bedrag. Boeken we hem, dan staat dezelfde
    // factuur twee keer in de boekhouding — dedup gaat op messageId en die is
    // anders. Dus: melding, en de eigenaar kijkt zelf of hij hem al heeft.
    return { invoice: null, notice: notice('reminder', note || 'Herinnering of aanmaning: controleer of deze factuur al in LaVega staat.'), dropped: null };
  }
  if (kind === 'receipt') {
    // Al betaald, dus het staat al in de bankafschriften. Als verwachte factuur
    // inboeken zou het bedrag dubbel in de prognose zetten.
    return { invoice: null, notice: null, dropped: 'betaalbewijs' };
  }
  if (kind !== 'invoice' || parsed.isInvoice !== true) {
    return { invoice: null, notice: null, dropped: 'geen factuur' };
  }

  const amountCents = toCents(parsed.amount);
  if (amountCents === null || amountCents <= 0) {
    // Het model zag wél een factuur maar geen bedrag. Niet boeken, en ook niet
    // stil weggooien: dan lijkt een gemiste factuur op geen factuur.
    return {
      invoice: null,
      notice: notice('no-amount', note || 'Het model herkende een factuur maar las er geen bedrag in. Zoek het bedrag zelf op.'),
      dropped: null,
    };
  }

  const currency = toText(parsed.currency, 3);
  return {
    invoice: Object.assign(/** @type {QueueInvoice} */ ({
      source: msg.source,
      messageId: msg.messageId,
      subject: String(msg.subject || '').slice(0, 200),
      // De afzender stond tot nu toe alleen op een MELDING. Op een factuurregel
      // hoort hij ook: bij een doorstuuradres is "wie stuurde dit" het enige
      // waarmee hij een regel kan beoordelen die hij niet verwachtte.
      from: String(msg.from || '').slice(0, 200),
      invoiceNumber: toText(parsed.invoiceNumber, 60),
      issueDate: toIsoDate(parsed.issueDate),
      dueDate: toIsoDate(parsed.dueDate),
      amountCents: amountCents,
      vatCents: toCents(parsed.vatAmount),
      // Geen valuta gelezen? Dan null, nooit stilzwijgend 'EUR' — zie de
      // systeemprompt en de Grenzen in FACTUREN.md.
      currency: currency && /^[A-Za-z]{3}$/.test(currency) ? currency.toUpperCase() : null,
      counterparty: toText(parsed.counterparty, 120),
      direction: parsed.direction === 'income' ? 'income' : 'expense',
      note: note || undefined,
    }), provenance),
    notice: null,
    dropped: null,
  };
}

/**
 * Een mail waar niets uit te lezen viel — geen tekst, geen PDF. Die gaat niet
 * naar het model (dat zou een leeg verzoek zijn, precies de fout die we aan het
 * repareren zijn) maar hij verdwijnt ook niet: hij wordt een melding.
 * @param {{source: string, messageId: string, subject: string, from: string, date: string, reason: string} & ProvenanceInput} msg
 * @returns {QueueNotice}
 */
function noticeForUnreadable(msg) {
  return Object.assign(
    /** @type {QueueNotice} */ ({
      source: msg.source,
      messageId: msg.messageId,
      subject: String(msg.subject || '').slice(0, 200),
      from: String(msg.from || '').slice(0, 200),
      receivedAt: String(msg.date || ''),
      kind: 'unreadable',
      reason: (msg.reason || 'Er viel niets uit deze mail te lezen.') + ' Open hem zelf.',
      mailUrl: mailUrlFor(msg),
    }),
    provenanceOf(/** @type {Record<string, unknown>} */ (/** @type {unknown} */ (msg))),
  );
}

// ── n8n-adapter ─────────────────────────────────────────────────────────
// Alles hierboven is LETTERLIJK gekopieerd uit packages/core/src/n8n/ en
// wordt daar getest. Wijzig het daar en draai `pnpm run sync:n8n`; wijzig je
// het hier of in de n8n-UI, dan valt `codeNodes.test.ts` om.

// Een mislukte modelaanroep mag NIET stil als "0 facturen" eindigen. De
// HTTP-node staat op continueRegularOutput zodat één rotte mail de run niet
// sloopt; dat verbergt ook een kapotte sleutel, dus tellen we de fouten en
// maken we de run rood als ALLES faalde.
const failed = (j) => !!(j && (j.error || j.type === 'error'));
const items = $input.all();
const errors = [];
for (const it of items) {
  const j = it.json || {};
  if (!failed(j)) continue;
  const e = j.error || j;
  errors.push(String((e && e.error && e.error.message) || (e && e.message) || 'onbekende fout').slice(0, 300));
}
if (errors.length > 0 && errors.length === items.length) {
  throw new Error('Alle modelaanroepen mislukten: ' + errors[0]);
}

const asked = $('Bouw Claude-verzoek').all();
const invoices = [];
const notices = [];
const dropped = [];
const processedIds = [];

for (let i = 0; i < items.length; i++) {
  const src = asked[i] ? asked[i].json : null;
  if (!src) continue;
  const j = items[i].json || {};
  // Deze mail is NIET beoordeeld. Niet onthouden als gezien, dus de volgende
  // run probeert hem opnieuw; de fout staat hieronder in de uitvoer.
  if (failed(j)) continue;
  const msg = {
    source: src.source,
    messageId: src.messageId,
    subject: src.subject,
    from: src.from,
    date: src.date,
    deliveredTo: src.deliveredTo,
    queueKey: src.queueKey,
    senderCheck: src.senderCheck,
    senderChecks: src.senderChecks,
  };
  const text = j.content && j.content[0] ? j.content[0].text : '';
  const entry = toQueueEntry(msg, parseModelJson(text));
  if (entry.invoice) invoices.push(entry.invoice);
  if (entry.notice) notices.push(entry.notice);
  if (entry.dropped) dropped.push(entry.dropped);
  processedIds.push(src.messageId);
}

// Eén verzoek met alles erin: LaVega zet ze in een wachtrij die JIJ bevestigt.
// Er wordt niets automatisch geboekt.
return [{ json: { invoices, notices, dropped, errors, processedIds } }];

/* De wachtrij in n8n: wat erin gaat, wat eruit valt, en wat we onthouden.
 *
 * DIT BESTAND DRAAIT OP TWEE PLEKKEN — het is de bron van de Code-node
 * "Zet in de wachtrij" in docs/n8n/lavega-invoices.json. `pnpm run sync:n8n`
 * kopieert het daarin. Geen TypeScript-syntax, alleen JSDoc.
 *
 * De rij blijft in n8n staan, niet op de LaVega-server: een factuurbedrag is
 * van de eigenaar, en de server hoeft het nooit te zien.
 *
 * `seenIds` is nieuw en lost een dure fout op. De schedule loopt elk uur over
 * dezelfde zeven dagen mail, en de rij wordt bij elk ophalen geleegd — dus
 * stond er niets in de weg om dezelfde mail (mét PDF, en dus met echte tokens)
 * tot wel 168 keer aan het model te sturen. Een messageId komt hier pas in
 * `seenIds` als het model hem ook echt beoordeeld heeft; mislukt de aanroep,
 * dan blijft hij onbekend en probeert de volgende run het opnieuw.
 */

/** Een rij die niemand ophaalt is een lek, geen archief. */
const MAX_QUEUE = 200;
const MAX_NOTICES = 200;
/** Genoeg voor zeven dagen mail met ruime marge; ouder dan dat valt toch buiten de zoekopdracht. */
const MAX_SEEN = 2000;

/**
 * @typedef {{ queue?: unknown, notices?: unknown, seenIds?: unknown }} QueueStore
 */

/**
 * @typedef {Object} QueueBatch
 * @property {{ messageId?: string }[]} invoices
 * @property {{ messageId?: string }[]} notices
 * @property {string[]} processedIds
 */

/**
 * @param {unknown} v
 * @returns {any[]}
 */
function asArray(v) {
  return Array.isArray(v) ? v : [];
}

/**
 * Voeg de uitkomst van één run toe aan de opgeslagen rij.
 * @param {QueueStore} store  $getWorkflowStaticData('global')
 * @param {QueueBatch} batch
 * @param {string} now        ISO-tijd; als parameter zodat een test hem vast kan zetten
 * @returns {{ addedInvoices: number, addedNotices: number, inQueue: number, noticesInQueue: number, remembered: number }}
 */
function addToQueue(store, batch, now) {
  const queue = asArray(store.queue);
  const notices = asArray(store.notices);
  const seenIds = asArray(store.seenIds);

  const seenInQueue = new Set(
    queue.map(function (row) {
      return row.messageId;
    }),
  );
  const seenInNotices = new Set(
    notices.map(function (row) {
      return row.messageId;
    }),
  );

  let addedInvoices = 0;
  for (const invoice of asArray(batch.invoices)) {
    if (!invoice.messageId || seenInQueue.has(invoice.messageId)) continue;
    seenInQueue.add(invoice.messageId);
    queue.push(Object.assign({}, invoice, { queuedAt: now }));
    addedInvoices++;
  }

  let addedNotices = 0;
  for (const notice of asArray(batch.notices)) {
    if (!notice.messageId || seenInNotices.has(notice.messageId)) continue;
    seenInNotices.add(notice.messageId);
    notices.push(Object.assign({}, notice, { queuedAt: now }));
    addedNotices++;
  }

  const remembered = new Set(seenIds);
  for (const id of asArray(batch.processedIds)) {
    if (id) remembered.add(id);
  }

  // Oudste eruit als het te lang wordt.
  store.queue = queue.length > MAX_QUEUE ? queue.slice(-MAX_QUEUE) : queue;
  store.notices = notices.length > MAX_NOTICES ? notices.slice(-MAX_NOTICES) : notices;
  const rememberedList = Array.from(remembered);
  store.seenIds = rememberedList.length > MAX_SEEN ? rememberedList.slice(-MAX_SEEN) : rememberedList;

  return {
    addedInvoices: addedInvoices,
    addedNotices: addedNotices,
    inQueue: asArray(store.queue).length,
    noticesInQueue: asArray(store.notices).length,
    remembered: asArray(store.seenIds).length,
  };
}

// ── n8n-adapter ─────────────────────────────────────────────────────────
// Alles hierboven is LETTERLIJK gekopieerd uit packages/core/src/n8n/ en
// wordt daar getest. Wijzig het daar en draai `pnpm run sync:n8n`; wijzig je
// het hier of in de n8n-UI, dan valt `codeNodes.test.ts` om.

// getWorkflowStaticData overleeft een run: n8n bewaart het bij de workflow in
// zijn eigen database.
const store = $getWorkflowStaticData('global');
const batch = { invoices: [], notices: [], processedIds: [] };
for (const item of $input.all()) {
  const j = item.json || {};
  for (const invoice of j.invoices || []) batch.invoices.push(invoice);
  for (const notice of j.notices || []) batch.notices.push(notice);
  for (const id of j.processedIds || []) batch.processedIds.push(id);
}
return [{ json: addToQueue(store, batch, new Date().toISOString()) }];

// LaVega vraagt de rij op. Wij geven hem en gooien hem weg: een lezer, een keer.
//
// Weggooien na uitlezen is bewust. Wat de browser heeft, staat versleuteld in
// de kluis; wat hier blijft staan, staat onversleuteld in de n8n-database. Hoe
// korter dat duurt, hoe beter.
//
// `notices` gaat mee in hetzelfde antwoord. Een melding heeft GEEN bedragveld
// en kan dus nooit een boeking worden; het is een briefje dat er iets op je
// wacht dat je zelf moet ophalen.
const store = $getWorkflowStaticData('global');
const invoices = Array.isArray(store.queue) ? store.queue : [];
const notices = Array.isArray(store.notices) ? store.notices : [];
store.queue = [];
store.notices = [];
return [{ json: { invoices, notices, servedAt: new Date().toISOString() } }];
